insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000001','60000000-0000-4000-8000-000000000001',coalesce(max(revision_number),0)+1,'published','Separate observed user behavior from assumptions and write a specific problem statement.','A useful problem statement starts with a person, a situation, and an obstacle that evidence can test.','[{"type":"heading","text":"Observe before naming a solution"},{"type":"paragraph","text":"Teams often start with a feature request: “We need reminders.” That is a proposed solution, not a description of the difficulty people face. Ask what happened, for whom, and in what setting. Mark what you observed separately from what you infer."},{"type":"callout","title":"Rootin example","text":"Three learners abandon a long setup form before creating their first routine. That is an observation. “They lack motivation” is an assumption. A narrower problem is that new learners cannot see value before setup asks for too much effort."},{"type":"paragraph","text":"A good frame remains open to several possible solutions. It names the user and context, explains the friction, and identifies what evidence is missing."}]'::jsonb,'[{"id":"problem-framing-initial-1","type":"single_choice","scenario":"A Rootin team sees many people leave during setup.","prompt":"Which statement is an observation?","options":[{"id":"a","text":"People leave the setup form before creating a routine."},{"id":"b","text":"People are not motivated enough."},{"id":"c","text":"The team should add badges."}],"tag":"problem-framing","difficulty":"applied","usage":"initial"},{"id":"problem-framing-initial-2","type":"single_choice","scenario":"A designer interviews two Slipboxd users who cannot find saved notes.","prompt":"Which problem frame keeps solutions open?","options":[{"id":"a","text":"Add a search bar immediately."},{"id":"b","text":"People retrieving older notes cannot locate them reliably."},{"id":"c","text":"The interface needs a blue navigation panel."}],"tag":"problem-framing","difficulty":"applied","usage":"initial"},{"id":"problem-framing-initial-3","type":"single_choice","scenario":"A stakeholder says users want AI summaries, but no users have been asked.","prompt":"What should the team do first?","options":[{"id":"a","text":"Ship summaries because the stakeholder is senior."},{"id":"b","text":"Treat the request as evidence of user demand."},{"id":"c","text":"Label the claim as an assumption and investigate the underlying task."}],"tag":"problem-framing","difficulty":"applied","usage":"initial"}]'::jsonb,'[{"id":"problem-framing-review-1","type":"single_choice","scenario":"A travel app receives complaints that booking takes too long.","prompt":"Which next step best clarifies the problem?","options":[{"id":"a","text":"Observe where and why bookings stall."},{"id":"b","text":"Immediately remove every booking field."},{"id":"c","text":"Launch a loyalty program."}],"tag":"problem-framing","difficulty":"applied","usage":"review"},{"id":"problem-framing-review-2","type":"single_choice","scenario":"A team claims students are lazy because they skip a tutorial.","prompt":"What is the strongest correction?","options":[{"id":"a","text":"State the observable skip behavior and test possible causes."},{"id":"b","text":"Call the skip a motivation problem."},{"id":"c","text":"Force every student to watch the video."}],"tag":"problem-framing","difficulty":"applied","usage":"review"}]'::jsonb,'[]'::jsonb,'For your project, write one observation, one assumption, and a problem statement that does not prescribe a feature.','lesson',9,now() from public.lesson_revisions where lesson_id='60000000-0000-4000-8000-000000000001' on conflict(id) do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000001','problem-framing-initial-1','a','"a"'::jsonb,'{"a":"Yes. This describes a visible behavior.","b":"Motivation is an explanation to test.","c":"A badge is a proposed solution."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000001','problem-framing-initial-2','b','"b"'::jsonb,'{"a":"This jumps to one solution.","b":"Yes. It identifies a user task and friction.","c":"This is a design prescription."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000001','problem-framing-initial-3','c','"c"'::jsonb,'{"a":"Authority is not user evidence.","b":"The request is a hypothesis, not observed demand.","c":"Yes. Find the task before committing to a solution."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000001','problem-framing-review-1','a','"a"'::jsonb,'{"a":"Yes. This separates friction from guessed fixes.","b":"Some fields may be needed; investigate first.","c":"This does not address booking friction."}'::jsonb,true) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000001','problem-framing-review-2','a','"a"'::jsonb,'{"a":"Yes. Keep observation and interpretation distinct.","b":"This repeats the unsupported assumption.","c":"This may add friction without learning why."}'::jsonb,true) on conflict do nothing;
insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000012',coalesce(max(revision_number),0)+1,'published','Describe a future user benefit and use it to choose between competing product ideas.','A product vision gives a team a direction beyond a feature list or a short-term target.','[{"type":"heading","text":"Name the future change"},{"type":"paragraph","text":"A vision describes the experience people should gain if the product succeeds. It is specific enough to guide trade-offs and broad enough to outlive one release. Features are possible means; metrics show whether progress occurred."},{"type":"callout","title":"Slipboxd example","text":"“Add tags and AI summaries” lists features. “Help researchers return to their own ideas and connect them when writing” describes a future benefit. The latter can guide which retrieval problem to solve first."},{"type":"paragraph","text":"A one-line exercise is only a starting point. Test the direction with evidence about users and use it when a tempting feature does not serve the intended benefit."}]'::jsonb,'[{"id":"product-vision-initial-1","type":"single_choice","scenario":"A team proposes badges, video playlists, and a streak counter for designers.","prompt":"Which direction is a product vision?","options":[{"id":"a","text":"Launch all three features this quarter."},{"id":"b","text":"Help designers turn fragmented learning into decisions they can use at work."},{"id":"c","text":"Increase registrations by 15%."}],"tag":"product-vision","difficulty":"applied","usage":"initial"},{"id":"product-vision-initial-2","type":"strongest_rationale","scenario":"Slipboxd can either improve note retrieval or add decorative themes.","prompt":"Which reason best uses its vision?","options":[{"id":"a","text":"Themes are easier to ship."},{"id":"b","text":"Retrieval helps researchers reconnect ideas when writing."},{"id":"c","text":"The competitor has themes."}],"tag":"product-vision","difficulty":"applied","usage":"initial"},{"id":"product-vision-initial-3","type":"single_choice","scenario":"A team has a compelling one-sentence vision but has never met a user.","prompt":"What should it do next?","options":[{"id":"a","text":"Treat the sentence as proof of demand."},{"id":"b","text":"Freeze all future product choices."},{"id":"c","text":"Investigate whether the intended benefit matches a real user need."}],"tag":"product-vision","difficulty":"applied","usage":"initial"}]'::jsonb,'[{"id":"product-vision-review-1","type":"single_choice","scenario":"A roadmap meeting turns into a list of requested features.","prompt":"Which question brings the team back to vision?","options":[{"id":"a","text":"Which request is cheapest?"},{"id":"b","text":"What future user benefit is each request meant to create?"},{"id":"c","text":"Which request has the most screens?"}],"tag":"product-vision","difficulty":"applied","usage":"review"},{"id":"product-vision-review-2","type":"single_choice","scenario":"A team says its vision is “reach 10,000 users by June.”","prompt":"What is missing?","options":[{"id":"a","text":"A named future benefit for a user."},{"id":"b","text":"A larger numeric target."},{"id":"c","text":"More detailed colors."}],"tag":"product-vision","difficulty":"applied","usage":"review"}]'::jsonb,'[{"type":"article","title":"Product Vision vs. Mission","url":"https://www.svpg.com/product-vision-vs-mission/","publisher":"SVPG · Marty Cagan","language":"en"}]'::jsonb,'Describe the future benefit your project should create for a specific user, then name one feature you might decline.','lesson',8,now() from public.lesson_revisions where lesson_id='10000000-0000-4000-8000-000000000012' on conflict(id) do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000002','product-vision-initial-1','b','"b"'::jsonb,'{"a":"This is a feature list.","b":"Yes. It describes a user and future benefit.","c":"This is a short-term target."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000002','product-vision-initial-2','b','"b"'::jsonb,'{"a":"Speed alone does not establish user benefit.","b":"Yes. It connects the choice to the future experience.","c":"Copying a competitor does not test the vision."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000002','product-vision-initial-3','c','"c"'::jsonb,'{"a":"A statement is not evidence.","b":"A vision should guide learning, not stop it.","c":"Yes. Validate the direction with users."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000002','product-vision-review-1','b','"b"'::jsonb,'{"a":"Cost matters later but cannot define direction.","b":"Yes. Test each idea against the intended change.","c":"Screen count does not express value."}'::jsonb,true) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000002','product-vision-review-2','a','"a"'::jsonb,'{"a":"Yes. The number is a metric, not a vision.","b":"Changing the target does not supply direction.","c":"Visual detail is unrelated."}'::jsonb,true) on conflict do nothing;
insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000003','60000000-0000-4000-8000-000000000002',coalesce(max(revision_number),0)+1,'published','Connect a specific user problem to a credible product benefit and its supporting reason.','A value proposition explains why a particular person would choose this solution for a real job.','[{"type":"heading","text":"Connect problem, benefit, and reason"},{"type":"paragraph","text":"Describe the user and their problem in plain language. Then explain the useful change your product promises and why your approach could deliver it. Avoid an inventory of capabilities without a reason to care."},{"type":"callout","title":"Slipboxd example","text":"For researchers who lose ideas across notebooks, Slipboxd makes earlier notes easy to rediscover while drafting. Links between related notes offer a plausible way to make that benefit real. Whether it works still needs testing."},{"type":"paragraph","text":"A credible proposition is a hypothesis until people use the product. Test whether the audience recognizes the problem and whether the proposed benefit changes their behavior."}]'::jsonb,'[{"id":"value-proposition-initial-1","type":"single_choice","scenario":"Slipboxd interviews researchers who lose useful notes while writing.","prompt":"Which message is clearest?","options":[{"id":"a","text":"A powerful platform with tags, themes, and widgets."},{"id":"b","text":"Find and connect your earlier notes when you need them in a draft."},{"id":"c","text":"The most innovative app available."}],"tag":"value-proposition","difficulty":"applied","usage":"initial"},{"id":"value-proposition-initial-2","type":"multiple_choice","scenario":"Rootin helps people begin a small routine.","prompt":"Which pieces belong in a value proposition?","options":[{"id":"a","text":"Specific user and problem."},{"id":"b","text":"Promised benefit."},{"id":"c","text":"Plausible reason the product helps."}],"tag":"value-proposition","difficulty":"applied","usage":"initial"},{"id":"value-proposition-initial-3","type":"single_choice","scenario":"A team has a polished claim but no sign that people care.","prompt":"What is the best next step?","options":[{"id":"a","text":"Publish the claim as proven."},{"id":"b","text":"Test the problem and benefit with target users."},{"id":"c","text":"Add more adjectives."}],"tag":"value-proposition","difficulty":"applied","usage":"initial"}]'::jsonb,'[{"id":"value-proposition-review-1","type":"single_choice","scenario":"A product page says “cloud-powered knowledge graph.”","prompt":"What improvement makes value clearer?","options":[{"id":"a","text":"Explain the researcher task and resulting benefit."},{"id":"b","text":"Add more technical terms."},{"id":"c","text":"Remove the target audience."}],"tag":"value-proposition","difficulty":"applied","usage":"review"},{"id":"value-proposition-review-2","type":"single_choice","scenario":"A value proposition promises instant confidence to every designer.","prompt":"What is its main weakness?","options":[{"id":"a","text":"It is too specific."},{"id":"b","text":"It lacks a credible, bounded benefit and audience."},{"id":"c","text":"It includes a user outcome."}],"tag":"value-proposition","difficulty":"applied","usage":"review"}]'::jsonb,'[]'::jsonb,'Write your target user, problem, promised benefit, and the reason your approach could deliver it.','lesson',9,now() from public.lesson_revisions where lesson_id='60000000-0000-4000-8000-000000000002' on conflict(id) do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000003','value-proposition-initial-1','b','"b"'::jsonb,'{"a":"This lists features without a job.","b":"Yes. It connects a task to a benefit.","c":"This claim has no concrete meaning."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000003','value-proposition-initial-2','a','["a","b","c"]'::jsonb,'{"a":"Yes. Name who benefits and why they struggle.","b":"Yes. State the useful change.","c":"Yes. Explain why this approach may work."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000003','value-proposition-initial-3','b','"b"'::jsonb,'{"a":"Polish does not validate value.","b":"Yes. Check recognition and behavior.","c":"Adjectives add no evidence."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000003','value-proposition-review-1','a','"a"'::jsonb,'{"a":"Yes. Translate capability into user value.","b":"Jargon can obscure the job.","c":"Audience specificity matters."}'::jsonb,true) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000003','value-proposition-review-2','b','"b"'::jsonb,'{"a":"It is actually broad and vague.","b":"Yes. Narrow the audience and claim.","c":"A user outcome alone is not enough."}'::jsonb,true) on conflict do nothing;
insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000004','60000000-0000-4000-8000-000000000003',coalesce(max(revision_number),0)+1,'published','Choose a minimal test that can challenge the riskiest assumption behind a product idea.','An MVP is a focused learning vehicle, not simply the smallest list of features.','[{"type":"heading","text":"Build to learn"},{"type":"paragraph","text":"List what must be true for the product direction to work. Choose the riskiest unknown and the smallest experience that could reveal whether it holds. Keep the test usable enough that behavior means something."},{"type":"callout","title":"Rootin example","text":"If the main risk is whether new users return to a routine, a simple daily check-in with a clear first action can test repeat use. A social feed and reward store would add scope without resolving that risk."},{"type":"paragraph","text":"State the trade-off. A narrow MVP may postpone polish or automation, but it must still let the target user experience the core benefit."}]'::jsonb,'[{"id":"mvp-scope-initial-1","type":"single_choice","scenario":"Rootin needs to learn whether people return after their first routine.","prompt":"Which MVP best tests that risk?","options":[{"id":"a","text":"A daily check-in and simple return path."},{"id":"b","text":"A full marketplace of routines."},{"id":"c","text":"A social feed before check-in works."}],"tag":"mvp-scope","difficulty":"applied","usage":"initial"},{"id":"mvp-scope-initial-2","type":"arrange_steps","scenario":"A team plans an MVP and has four activities.","prompt":"Which order supports learning?","options":[{"id":"a","text":"Identify risky assumption."},{"id":"b","text":"Define observable signal."},{"id":"c","text":"Build a minimal usable experience."},{"id":"d","text":"Observe users and decide."}],"tag":"mvp-scope","difficulty":"applied","usage":"initial"},{"id":"mvp-scope-initial-3","type":"single_choice","scenario":"A team wants to cut onboarding so much that users cannot reach the core task.","prompt":"What is the best response?","options":[{"id":"a","text":"Keep the cut because fewer screens always means MVP."},{"id":"b","text":"Retain the minimum path to the core benefit."},{"id":"c","text":"Add every planned feature back."}],"tag":"mvp-scope","difficulty":"applied","usage":"initial"}]'::jsonb,'[{"id":"mvp-scope-review-1","type":"single_choice","scenario":"A team builds ten features to test whether anyone wants note retrieval.","prompt":"What should it narrow first?","options":[{"id":"a","text":"The assumption and behavior to observe."},{"id":"b","text":"The color palette."},{"id":"c","text":"The team logo."}],"tag":"mvp-scope","difficulty":"applied","usage":"review"},{"id":"mvp-scope-review-2","type":"single_choice","scenario":"An MVP receives clicks but no completed core tasks.","prompt":"Which inference is strongest?","options":[{"id":"a","text":"The product is validated."},{"id":"b","text":"Clicks alone do not prove the promised benefit was reached."},{"id":"c","text":"The team should immediately scale marketing."}],"tag":"mvp-scope","difficulty":"applied","usage":"review"}]'::jsonb,'[]'::jsonb,'Name your riskiest assumption, your smallest meaningful test, and one feature you will defer.','lesson',10,now() from public.lesson_revisions where lesson_id='60000000-0000-4000-8000-000000000003' on conflict(id) do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000004','mvp-scope-initial-1','a','"a"'::jsonb,'{"a":"Yes. This observes repeat behavior directly.","b":"This adds broad scope before testing return use.","c":"This tests sharing, not the central risk."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000004','mvp-scope-initial-2','a','["a","b","c","d"]'::jsonb,'{"a":"Start with the unknown that could break the idea.","b":"Decide what evidence would change your mind.","c":"Build only what lets users experience the benefit.","d":"Use observed behavior to make the next choice."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000004','mvp-scope-initial-3','b','"b"'::jsonb,'{"a":"An unusable test gives weak evidence.","b":"Yes. Minimal still needs meaningful use.","c":"A full build is not required."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000004','mvp-scope-review-1','a','"a"'::jsonb,'{"a":"Yes. Scope follows the learning question.","b":"Visual style does not define the risk.","c":"Branding does not test demand."}'::jsonb,true) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000004','mvp-scope-review-2','b','"b"'::jsonb,'{"a":"Interest is not completed value.","b":"Yes. Inspect the core outcome.","c":"Promotion cannot fix an unproven experience."}'::jsonb,true) on conflict do nothing;
insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000005','60000000-0000-4000-8000-000000000004',coalesce(max(revision_number),0)+1,'published','Choose an outcome measure that shows whether the target user receives the intended benefit.','Counts of screens, releases, and clicks tell you what happened in the product, but rarely whether life improved for a user.','[{"type":"heading","text":"Match the measure to the promise"},{"type":"paragraph","text":"Begin with the change in the product vision. Choose a user behavior that would plausibly indicate that change, specify when it should happen, and pair it with a guardrail for harmful side effects."},{"type":"callout","title":"Slipboxd example","text":"If Slipboxd promises useful retrieval during writing, a stronger measure is the share of drafting sessions in which a saved note is found and used. Total notes created is easier to count but does not prove retrieval value."},{"type":"paragraph","text":"Metrics are signals, not proof on their own. Combine behavior with qualitative evidence and watch for unintended incentives."}]'::jsonb,'[{"id":"outcome-metrics-initial-1","type":"single_choice","scenario":"Slipboxd wants researchers to use earlier ideas when drafting.","prompt":"Which metric is closest to that outcome?","options":[{"id":"a","text":"Number of buttons shipped."},{"id":"b","text":"Share of drafting sessions using a retrieved saved note."},{"id":"c","text":"Total account signups."}],"tag":"outcome-metrics","difficulty":"applied","usage":"initial"},{"id":"outcome-metrics-initial-2","type":"single_choice","scenario":"Rootin sees more notification opens but fewer completed routines.","prompt":"What should the team conclude?","options":[{"id":"a","text":"Notifications solved the problem."},{"id":"b","text":"Opens are a proxy; investigate completed routines and possible harm."},{"id":"c","text":"Send twice as many notifications."}],"tag":"outcome-metrics","difficulty":"applied","usage":"initial"},{"id":"outcome-metrics-initial-3","type":"arrange_steps","scenario":"A team wants to pick a measure before launch.","prompt":"Which sequence is most sensible?","options":[{"id":"a","text":"Name the intended benefit."},{"id":"b","text":"Choose observable user behavior."},{"id":"c","text":"Set a timeframe and guardrail."},{"id":"d","text":"Review the signal with user context."}],"tag":"outcome-metrics","difficulty":"applied","usage":"initial"}]'::jsonb,'[{"id":"outcome-metrics-review-1","type":"single_choice","scenario":"A learning app celebrates minutes spent even when learners cannot apply ideas.","prompt":"What should it measure instead?","options":[{"id":"a","text":"A behavior showing successful application."},{"id":"b","text":"More time in app regardless of benefit."},{"id":"c","text":"Number of animations shipped."}],"tag":"outcome-metrics","difficulty":"applied","usage":"review"},{"id":"outcome-metrics-review-2","type":"single_choice","scenario":"A metric rises after a redesign, but interviews reveal confusion.","prompt":"What is the best response?","options":[{"id":"a","text":"Ignore interviews because the number rose."},{"id":"b","text":"Use both signals and inspect the behavior behind the number."},{"id":"c","text":"Declare a universal success."}],"tag":"outcome-metrics","difficulty":"applied","usage":"review"}]'::jsonb,'[]'::jsonb,'Choose one outcome metric, its timeframe, and one guardrail for your project.','lesson',9,now() from public.lesson_revisions where lesson_id='60000000-0000-4000-8000-000000000004' on conflict(id) do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000005','outcome-metrics-initial-1','b','"b"'::jsonb,'{"a":"Output does not show user benefit.","b":"Yes. This reflects the promised task.","c":"Acquisition is not retrieval value."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000005','outcome-metrics-initial-2','b','"b"'::jsonb,'{"a":"The core outcome moved the other way.","b":"Yes. Compare proxy and outcome.","c":"More volume may worsen the experience."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000005','outcome-metrics-initial-3','a','["a","b","c","d"]'::jsonb,'{"a":"Begin with the desired change.","b":"Translate it into a behavior.","c":"Bound the measure and watch side effects.","d":"Interpret numbers alongside context."}'::jsonb,false) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000005','outcome-metrics-review-1','a','"a"'::jsonb,'{"a":"Yes. Align the signal with learning benefit.","b":"Time can reward friction.","c":"Shipping work is not learning."}'::jsonb,true) on conflict do nothing;
insert into private.answer_keys(revision_id,question_id,correct_option_id,correct_answer,explanations,review) values('70000000-0000-4000-8000-000000000005','outcome-metrics-review-2','b','"b"'::jsonb,'{"a":"One number is incomplete evidence.","b":"Yes. Investigate the apparent conflict.","c":"The evidence is mixed."}'::jsonb,true) on conflict do nothing;
insert into public.lesson_revisions(id,lesson_id,revision_number,state,outcome,introduction,content,question_public,review_public,resource_cards,reflection_prompt,completion_policy,estimated_minutes,published_at) select '70000000-0000-4000-8000-000000000006','60000000-0000-4000-8000-000000000005',coalesce(max(revision_number),0)+1,'published','Combine a problem, vision, value, MVP, and measure into a coherent direction.','Apply the unit to one project and keep evidence distinct from assumptions.','[{"type":"paragraph","text":"Choose Rootin, Slipboxd, or your own project. Explain who you serve, the problem and its evidence, the future benefit, a focused first test, the outcome measure, and the trade-off. Your self-assessment helps you revise; it is not a professional grade."}]'::jsonb,'[]','[]','[]','Reflect on what evidence would most change your direction.','checkpoint',25,now() from public.lesson_revisions where lesson_id='60000000-0000-4000-8000-000000000005' on conflict(id) do nothing;
insert into public.curriculum_versions(id,track_id,version_number,manifest) values('40000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001',2,'["60000000-0000-4000-8000-000000000001","10000000-0000-4000-8000-000000000012","60000000-0000-4000-8000-000000000002","60000000-0000-4000-8000-000000000003","60000000-0000-4000-8000-000000000004","60000000-0000-4000-8000-000000000005"]'::jsonb) on conflict(track_id,version_number) do nothing;
